{
  "name": "memoflow-development",
  "version": "0.1.6",
  "private": true,
  "type": "module",
  "scripts": {
    "check:web": "vue-tsc --noEmit -p frontend/tsconfig.json",
    "build:web": "npm run check:web && vite build --config frontend/vite.config.ts",
    "test:web": "tsx --test tests/test_frontend.ts tests/test_i18n.ts",
    "test:browser": "tsx --test tests/test_browser.ts tests/test_review_browser.ts",
    "render:uml": "tsx scripts/render_uml.ts",
    "check:uml": "tsc --noEmit --strict --skipLibCheck --types node --target ES2022 --module NodeNext --moduleResolution NodeNext scripts/render_uml.ts"
  },
  "dependencies": {
    "@element-plus/icons-vue": "2.3.2",
    "element-plus": "2.14.7",
    "vue": "3.5.43"
  },
  "devDependencies": {
    "@types/node": "24.10.1",
    "@vitejs/plugin-vue": "6.0.9",
    "mermaid": "11.12.0",
    "playwright": "1.62.1",
    "tsx": "4.23.15",
    "typescript": "6.0.3",
    "vite": "8.3.2",
    "vue-tsc": "3.3.12"
  },
  "engines": {
    "node": "^20.19.0 || >=22.12.0"
  }
}

{
  "name": "asr-transcription-bailian-runtime",
  "version": "0.1.6",
  "private": true,
  "dependencies": {
    "bailian-cli": "2.10.1"
  }
}

import { createApp } from "vue";
import "element-plus/dist/index.css";
import "element-plus/theme-chalk/dark/css-vars.css";
import "./style.css";
import App from "./App.vue";
import ReviewApp from "./ReviewApp.vue";
import { createReviewApi } from "./review";
import { createApi } from "./api";
import type { Language } from "./types";
import type { Translate } from "./i18n";

if (window.location.pathname === "/review") {
  createApp(ReviewApp, { connect: (language: () => Language, t: Translate) => createReviewApi(window.fetch.bind(window), language, t) }).mount("#app");
} else {
  createApp(App, { connect: (language: () => Language, t: Translate) => createApi(window.fetch.bind(window), language, t) }).mount("#app");
}

# Code of Conduct

MemoFlow welcomes useful, respectful participation.

Participants should:

- discuss the work and its evidence rather than people;
- explain problems with enough detail for others to reproduce them;
- respect different levels of experience and language background;
- protect private recordings, credentials, and personal information.

Harassment, discrimination, personal attacks, deliberate exposure of private data, and malicious submissions are not acceptable. Project maintainers may remove content or restrict participation when needed to keep the project safe and constructive.

For sensitive reports, contact the repository owner privately instead of posting credentials or private recordings in a public Issue.

# Support

For installation and usage questions, start with the [usage guide](skills/asr-transcription/references/usage.md) and [troubleshooting guide](skills/asr-transcription/references/errors.md).

Use [Discussions](https://github.com/hx101700/memoflow/discussions) for questions, workflows, and feature ideas. Use [Issues](https://github.com/hx101700/memoflow/issues) for reproducible bugs.

When reporting a problem, include:

- Windows version and architecture;
- package name and release version;
- the step that failed;
- the exact redacted error message;
- whether the failure is repeatable.

Redact API keys, login URLs, private recordings, transcript content, and personal paths before sharing your report.
